#!/usr/bin/env node
/* Import the owner-supplied HSAI launcher icon, or emit a neutral placeholder.
 *
 * The final launcher artwork is intentionally NOT generated by this project.
 * Put a PNG at assets/icon/icon.png (1024×1024 recommended, transparency
 * supported) and run `npm run assets`. The supplied pixels are copied
 * byte-for-byte into the Android resources; nothing is redrawn, cropped,
 * recoloured or otherwise "improved".
 *
 * With no icon.png present, a clearly temporary dark placeholder is installed
 * so the APK still builds. It is not the HSAI brand icon.
 *
 * Pure Node (zlib only) — no image library, no sharp, no native binaries.
 */
import { copyFileSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { deflateSync } from "node:zlib";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const RES = join(ROOT, "android", "app", "src", "main", "res");
const ICON_SOURCE = join(ROOT, "assets", "icon", "icon.png");

const CYAN = [88, 231, 255];
const DARK = [2, 7, 10];

/* ---------------------------------------------------------------- PNG writer */
const CRC_TABLE = (() => {
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[n] = c >>> 0;
  }
  return table;
})();

function crc32(buffer) {
  let crc = 0xffffffff;
  for (const byte of buffer) crc = CRC_TABLE[(crc ^ byte) & 0xff] ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}

function chunk(type, data) {
  const length = Buffer.alloc(4);
  length.writeUInt32BE(data.length, 0);
  const body = Buffer.concat([Buffer.from(type, "ascii"), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body), 0);
  return Buffer.concat([length, body, crc]);
}

function writePNG(file, width, height, shade) {
  const stride = width * 4;
  const raw = Buffer.alloc(height * (stride + 1));
  for (let y = 0; y < height; y++) {
    const row = y * (stride + 1);
    raw[row] = 0; // filter: none
    for (let x = 0; x < width; x++) {
      const [r, g, b, a] = shade(x, y, width, height);
      const p = row + 1 + x * 4;
      raw[p] = r;
      raw[p + 1] = g;
      raw[p + 2] = b;
      raw[p + 3] = a;
    }
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 6; // truecolour + alpha
  const png = Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk("IHDR", ihdr),
    chunk("IDAT", deflateSync(raw, { level: 9 })),
    chunk("IEND", Buffer.alloc(0)),
  ]);
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, png);
}

/* ------------------------------------------------------------- placeholder art */
const TAU = Math.PI * 2;

function blend(base, top, alpha) {
  const a = Math.max(0, Math.min(1, alpha));
  return [
    Math.round(base[0] * (1 - a) + top[0] * a),
    Math.round(base[1] * (1 - a) + top[1] * a),
    Math.round(base[2] * (1 - a) + top[2] * a),
  ];
}

const BLUE = [37, 99, 235];
const WHITE = [255, 255, 255];
const DEEP_NAVY = [4, 13, 26];

/** Futuristic VDPAI icon: glowing planetary arc reactor with radiant 4-point star. */
function vdpaiIconShader(round, foreground = false) {
  return (x, y, w, h) => {
    const size = Math.min(w, h);
    const u = (x - w / 2) / size;
    const v = (y - h / 2) / size;
    const radius = Math.hypot(u, v);

    // 4-point sparkle star center at (0.10, -0.10)
    const su = u - 0.10;
    const sv = v - (-0.10);
    const sdist = Math.hypot(su, sv);
    // Cross sparkle arms
    const starArmH = Math.max(0, 1 - Math.abs(su) / 0.14) * Math.max(0, 1 - Math.abs(sv) / 0.035);
    const starArmV = Math.max(0, 1 - Math.abs(sv) / 0.14) * Math.max(0, 1 - Math.abs(su) / 0.035);
    const starCore = Math.max(0, 1 - sdist / 0.045);
    const starIntensity = Math.min(1, starArmH * 1.5 + starArmV * 1.5 + starCore * 2.2);

    // Planetary arc ring centered at (-0.02, 0.03)
    const ru = u - (-0.02);
    const rv = v - 0.03;
    const rdist = Math.hypot(ru, rv);
    const ringDist = Math.abs(rdist - 0.22);
    const ringIntensity = Math.max(0, 1 - ringDist / 0.055);

    if (foreground) {
      if (starIntensity <= 0.02 && ringIntensity <= 0.02) return [0, 0, 0, 0];
      let col = blend(BLUE, CYAN, ringIntensity);
      if (starIntensity > 0.05) col = blend(col, WHITE, starIntensity);
      const alpha = Math.min(1, ringIntensity * 1.8 + starIntensity * 2.5);
      return [...col, Math.round(255 * alpha)];
    }

    // Squircle boundary
    const squircle = Math.pow(Math.abs(u / 0.44), 4) + Math.pow(Math.abs(v / 0.44), 4);
    if ((round && radius > 0.5) || squircle > 1.0) return [0, 0, 0, 0];

    // Background gradient
    let bg = blend(DARK, DEEP_NAVY, Math.max(0, 1 - radius / 0.6));
    // Soft core ambient bloom
    bg = blend(bg, CYAN, Math.max(0, 1 - radius / 0.45) * 0.15);
    // Ring glow
    if (ringIntensity > 0) {
      const ringCol = blend(BLUE, CYAN, ringIntensity);
      bg = blend(bg, ringCol, ringIntensity * 0.9);
    }
    // Star sparkle
    if (starIntensity > 0) {
      bg = blend(bg, WHITE, starIntensity * 0.95);
    }
    return [...bg, 255];
  };
}

function splash(scale) {
  return (x, y, w, h) => {
    const size = Math.min(w, h);
    const u = (x - w / 2) / size;
    const v = (y - h / 2) / size;
    const radius = Math.hypot(u, v);
    let color = blend(DARK, DEEP_NAVY, Math.max(0, 1 - radius / (0.85 * scale)) ** 2 * 0.2);
    // Subtle central reactor glow
    const core = Math.max(0, 1 - radius / (0.35 * scale));
    color = blend(color, CYAN, core * 0.25);
    return [...color, 255];
  };
}

/* ---------------------------------------------------------------------- emit */
const DENSITIES = [
  ["mdpi", 48],
  ["hdpi", 72],
  ["xhdpi", 96],
  ["xxhdpi", 144],
  ["xxxhdpi", 192],
];

const SPLASHES = [
  ["drawable", 480, 320],
  ["drawable-port-mdpi", 320, 480],
  ["drawable-port-hdpi", 480, 800],
  ["drawable-port-xhdpi", 720, 1280],
  ["drawable-port-xxhdpi", 960, 1600],
  ["drawable-port-xxxhdpi", 1280, 1920],
  ["drawable-land-mdpi", 480, 320],
  ["drawable-land-hdpi", 800, 480],
  ["drawable-land-xhdpi", 1280, 720],
  ["drawable-land-xxhdpi", 1600, 960],
  ["drawable-land-xxxhdpi", 1920, 1280],
];

for (const [dir, width, height] of SPLASHES) {
  writePNG(join(RES, dir, "splash.png"), width, height, splash(0.55));
}

function writeAdaptiveIcons(foregroundDrawable) {
  for (const file of ["ic_launcher.xml", "ic_launcher_round.xml"]) {
    writeFileSync(
      join(RES, "mipmap-anydpi-v26", file),
      `<?xml version="1.0" encoding="utf-8"?>\n` +
        `<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">\n` +
        `    <background android:drawable="@color/ic_launcher_background" />\n` +
        `    <foreground android:drawable="${foregroundDrawable}" />\n` +
        `</adaptive-icon>\n`,
      "utf8",
    );
  }
}

function removeGeneratedIcons() {
  for (const [density] of DENSITIES) {
    for (const name of ["ic_launcher.png", "ic_launcher_round.png", "ic_launcher_foreground.png"]) {
      rmSync(join(RES, `mipmap-${density}`, name), { force: true });
    }
  }
}

function removeImportArtifacts() {
  rmSync(join(RES, "drawable-nodpi", "ic_launcher_user.png"), { force: true });
  rmSync(join(RES, "drawable", "ic_launcher_user_inset.xml"), { force: true });
}

function readPngSize(file) {
  const data = readFileSync(file);
  const signature = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
  if (data.length < 24 || !data.subarray(0, 8).equals(signature) || data.toString("ascii", 12, 16) !== "IHDR") {
    throw new Error("assets/icon/icon.png is not a valid PNG file.");
  }
  return { width: data.readUInt32BE(16), height: data.readUInt32BE(20), bytes: data.length };
}

const hasSource = existsSync(ICON_SOURCE) && readFileSync(ICON_SOURCE).length > 0;

if (hasSource) {
  const size = readPngSize(ICON_SOURCE);
  removeGeneratedIcons();
  removeImportArtifacts();

  // The supplied PNG is copied unchanged. Density-aware scaling is left to
  // Android; copying instead of resampling guarantees no colour or alpha loss.
  for (const [density] of DENSITIES) {
    mkdirSync(join(RES, `mipmap-${density}`), { recursive: true });
    copyFileSync(ICON_SOURCE, join(RES, `mipmap-${density}`, "ic_launcher.png"));
    copyFileSync(ICON_SOURCE, join(RES, `mipmap-${density}`, "ic_launcher_round.png"));
  }
  mkdirSync(join(RES, "drawable-nodpi"), { recursive: true });
  mkdirSync(join(RES, "drawable"), { recursive: true });
  copyFileSync(ICON_SOURCE, join(RES, "drawable-nodpi", "ic_launcher_user.png"));

  writeFileSync(
    join(RES, "drawable", "ic_launcher_user_inset.xml"),
    `<?xml version="1.0" encoding="utf-8"?>\n` +
      `<!-- Insets the owner-supplied artwork into the adaptive-icon safe zone. -->\n` +
      `<inset xmlns:android="http://schemas.android.com/apk/res/android"\n` +
      `    android:drawable="@drawable/ic_launcher_user"\n` +
      `    android:inset="18%" />\n`,
    "utf8",
  );
  writeAdaptiveIcons("@drawable/ic_launcher_user_inset");
  rmSync(join(RES, "drawable", "ic_launcher_background.xml"), { force: true });
  rmSync(join(RES, "drawable-v24", "ic_launcher_foreground.xml"), { force: true });

  console.log(
    `[hsai] Imported assets/icon/icon.png (${size.width}×${size.height}, ${Math.round(size.bytes / 1024)} KiB) unchanged.`,
  );
} else {
  removeImportArtifacts();

  for (const [density, size] of DENSITIES) {
    const dir = join(RES, `mipmap-${density}`);
    writePNG(join(dir, "ic_launcher.png"), size, size, vdpaiIconShader(false));
    writePNG(join(dir, "ic_launcher_round.png"), size, size, vdpaiIconShader(true));
    const fgSize = Math.round(size * (108 / 48));
    writePNG(join(dir, "ic_launcher_foreground.png"), fgSize, fgSize, vdpaiIconShader(false, true));
  }
  writeAdaptiveIcons("@mipmap/ic_launcher_foreground");

  // Also write the master 512x512 icon for web / icon.png
  writePNG(ICON_SOURCE, 512, 512, vdpaiIconShader(false));

  console.log("[vdpai] VDPAI futuristic launcher icons and master artwork generated.");
}

console.log("[vdpai] Android splash screens generated (VDPAI cosmic reactor theme).");
